/**
 * O transporte de oxigênio — porte de `componentes/viz/hemoglobina.js`.
 *
 * A hemoglobina tem de fazer duas coisas opostas: AGARRAR o oxigênio no pulmão e
 * SOLTAR o mesmo oxigênio no tecido. Afinidade alta demais e ela carrega tudo e
 * não entrega nada; baixa demais e nem chega a carregar. A entrega é o produto
 * das duas, e por isso tem um ponto ótimo no meio.
 *
 * A cena é a viagem de ida e volta de uma hemácia, com os quatro sítios de
 * ligação visíveis — carregando de um lado, soltando do outro.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const hemoglobina: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** Uma molécula de O₂ — dois átomos colados. */
  function o2(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, cor: string): void {
    ctx.fillStyle = cor;
    ctx.beginPath();
    ctx.arc(x - r * 0.55, y, r, 0, Math.PI * 2);
    ctx.arc(x + r * 0.55, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const afinidade = numeroDe(valores, 'af', 0);
    const entrega = numeroDe(info, 'entrega', 0);
    const ok = info.ok === true;
    const carregados = Math.round((4 * afinidade) / 100);
    const soltos = limitar(Math.round((4 * entrega) / 100), 0, carregados);

    titulo(ctx, L, A, 'Agarrar de um lado, soltar do outro');

    // Os dois territórios.
    ctx.fillStyle = 'rgb(60 74 158 / 12%)';
    ctx.fillRect(0, A * 0.16, L * 0.5, A * 0.84);
    ctx.fillStyle = 'rgb(201 74 69 / 12%)';
    ctx.fillRect(L * 0.5, A * 0.16, L * 0.5, A * 0.84);

    ctx.strokeStyle = cor.trilho;
    ctx.setLineDash([5, 5]);
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(L * 0.5, A * 0.16);
    ctx.lineTo(L * 0.5, A);
    ctx.stroke();
    ctx.setLineDash([]);

    const miudo = limitar(A * 0.038, 9, 12);
    texto(ctx, 'PULMÃO — rico em O₂', L * 0.25, A * 0.22, miudo, { cor: cor.azul, peso: 800 });
    texto(ctx, 'TECIDO — precisa de O₂', L * 0.75, A * 0.22, miudo, { cor: cor.erro, peso: 800 });

    // O₂ livre boiando no pulmão.
    for (let i = 0; i < 7; i++) {
      const x = 24 + ((i * 41 + t * 22) % (L * 0.5 - 48));
      const y = A * 0.3 + ((i * 57) % (A * 0.58));
      o2(ctx, x, y, 5, cor.azulClaro);
    }

    // A hemácia, indo e voltando.
    const fase = Math.sin(t * 0.7) * 0.5 + 0.5;
    const cx = L * 0.18 + fase * (L * 0.64);
    const cy = A * 0.64;

    ctx.fillStyle = ok ? '#d2405a' : '#b03a50';
    ctx.beginPath();
    ctx.ellipse(cx, cy, 34, 24, 0, 0, Math.PI * 2);
    ctx.fill();

    // A depressão central — é o que faz ler como disco bicôncavo, e não bolinha.
    ctx.fillStyle = 'rgb(120 20 35 / 45%)';
    ctx.beginPath();
    ctx.ellipse(cx, cy, 17, 12, 0, 0, Math.PI * 2);
    ctx.fill();

    // Os quatro sítios de ligação. No tecido, os entregues ficam vazios.
    const presos = fase < 0.5 ? carregados : Math.max(0, carregados - soltos);
    for (let s = 0; s < 4; s++) {
      const a = (s / 4) * Math.PI * 2 - Math.PI / 2;
      const ox = cx + Math.cos(a) * 22;
      const oy = cy + Math.sin(a) * 15;

      if (s < presos) {
        o2(ctx, ox, oy, 5, cor.azulClaro);
      } else {
        ctx.strokeStyle = cor.contraste;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(ox, oy, 5, 0, Math.PI * 2);
        ctx.stroke();
      }
    }

    // O que foi de fato entregue ao tecido.
    if (fase > 0.5) {
      for (let i = 0; i < soltos; i++) {
        const x = cx + 30 + i * 18;
        const y = cy - 12 + ((t * 34 + i * 20) % 40);
        o2(ctx, x, y, 4, cor.azulClaro);
      }
    }

    // A barra de entrega — o número que o módulo persegue.
    const gx = L - 14;
    const gy = A * 0.3;
    const gh = A * 0.52;
    retangulo(ctx, gx, gy, 9, gh, 4, cor.trilho);
    const cheia = (gh * limitar(entrega, 0, 100)) / 100;
    retangulo(ctx, gx, gy + gh - cheia, 9, cheia, 4, ok ? cor.verde : cor.ouro);

    texto(ctx, `entrega ${Math.round(entrega)}%`, gx - 6, gy + 8, miudo, {
      cor: ok ? cor.verde : cor.fraco,
      alinhamento: 'right',
      peso: 700,
    });
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default hemoglobina;
